        if i >= n-2:
            return
        arr[i], arr[i+2], arr[i+1] = arr[i+2], arr[i], arr[i+1]
        operations.append(i)

    for _ in range(n**2):
        if is_sorted():
            return operations
        max_val = max(arr)
        max_idx = arr.index(max_val)
        if max_idx == n-1:
            continue
        if max_idx == n-2:
            rotate(max_idx-1)
            continue
        if arr[max_idx+1] < arr[max_idx-1]:
            rotate(max_idx-1)
        else:
            rotate(max_idx)
    return [-1]

