import fractions

def decompose(n):
    if isinstance(n, str):
        num, den = map(int, n.split('/'))
    elif isinstance(n, (int, float)):
        n = fractions.Fraction(n)
        num, den = n.numerator, n.denominator
    else:
        raise TypeError('Unsupported type')

    if num == 0:
        return []

    result = []
    while num > 0:
        next_den = den
        while True:
            next_num = num - 1
            if next_num % next_den == 0:
                break
            next_den += 1
        result.append(fractions.Fraction(next_num // next_den, next_den))
        num -= next_num // next_den
        den = next_den
    return result

