def prod_int_partII(n, s):
    def factorize(x):
        factors = []
        for i in range(2, isqrt(x) + 1):
            count = 0
            while x % i == 0:
                x //= i
                count += 1
            if count > 0:
                factors.append((i, count))
        if x > 1:
            factors.append((x, 1))
        return factors

