            if len(current_partition) == s:
                partitions.append(sorted(current_partition))
            return
        for i in range(index, len(factors)):
            factor, count = factors[i]
            for j in range(count + 1):
                generate_partitions(factors[i+1:], target // pow(factor, j), current_partition + [factor] * j, i)

    partitions = []
    factorize(n)
    generate_partitions(factorize(n), n, [], 0)

