def interpreter(code, tape):
    tape = list(map(int, tape))
    pointer = 0
    pc = 0  # Program Counter
    stack = []

    while pc < len(code):
        cmd = code[pc]

        if cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == '*':
            tape[pointer] ^= 1
        elif cmd == '[' and tape[pointer] == 0:
            stack.append(pc)
        elif cmd == ']' and tape[pointer] != 0:
            pc = stack[-1] + tape[pointer]
            stack.pop()
        elif cmd == '[' or cmd == ']':
            pass  # Ignore non-command characters

        pc += 1
        if pointer < 0 or pointer >= len(tape):
            break

    return ''.join(map(str, tape))
